import { computed, defineStore, signal } from '@pyreon/store'
type Item = { id: string; price: number }

const useCart = defineStore('cart', () => {
  const items = signal<Item[]>([])
  const total = computed(() => items().reduce((n, i) => n + i.price, 0))
  const add = (item: Item) => items.update((xs) => [...xs, item])
  const clear = () => items.set([])
  return { items, total, add, clear }
})

function CartTotal() {
  const { store } = useCart()
  return <span>{store.total()}</span> // only this text node updates
}

