import { defineStore, signal } from '@pyreon/store'

const useDoc = defineStore('doc', () => {
  const title = signal('Untitled')
  const body = signal('')
  const rename = (t: string) => title.set(t)
  return { title, body, rename }
})

const doc = useDoc()
const history: Record<string, unknown>[] = []

// one argument: the mutation. Its state snapshot is built only if you read it.
doc.subscribe((mutation) => {
  history.push(mutation.state)
})
// every action, with its arguments and result: for logging, analytics, undo
doc.onAction(({ name, args, after }) => {
  after(() => console.log(`${name}(${JSON.stringify(args)})`))
})

doc.store.rename('Launch plan') // logs: rename(["Launch plan"])
doc.patch({ body: 'Ship on Monday' })

const undo = () => {
  history.pop()
  doc.patch(history.at(-1) ?? { title: 'Untitled', body: '' })
  history.pop() // drop the snapshot the undo itself produced
}
undo()
console.log(doc.store.title(), JSON.stringify(doc.store.body())) // 'Launch plan' ''

import { defineSchemaStore } from '@pyreon/store'
import { z } from 'zod'

const useSettings = defineSchemaStore('settings', {
  schema: z.object({
    theme: z.enum(['light', 'dark', 'system']),
    fontSize: z.number().int().min(10).max(32),
  }),
  initial: { theme: 'system', fontSize: 14 },
})

const settings = useSettings()
settings.patch({ fontSize: 18 }) // validated, typed from the schema

try {
  settings.patch({ fontSize: 99 }) // rejected: the store keeps 18
} catch (e) {
  console.log((e as Error).message)
}
console.log(settings.store.fontSize()) // 18
